<script>
import { defineComponent, ref, reactive, computed, onMounted } from 'vue'

export default defineComponent({
  name: 'DncDashboard',
  setup () {
    const loading = ref(false)
    const nvrConfig = reactive({})
    const nvrStatus = reactive({ connected: false, isDemo: false })
    const allCameras = ref([])
    const activeSessions = ref([])
    const systemUsers = ref([])
    const aiConfig = reactive({ vlm: { model_name: 'GLM-5.3-Flash' } })
    const cosmosPrompt = reactive({})
    const listenerStatus = reactive({})

    const activeCamerasCount = computed(() => {
      return allCameras.value.filter(c => c.is_active).length
    })

    const loadData = async () => {
      loading.value = true
      try {
        const [nvrRes, camRes, sessRes, userRes, aiRes, cosRes, lisRes] = await Promise.allSettled([
          fetch('/api/config/nvr').then(r => r.json()),
          fetch('/api/admin/cameras/all').then(r => r.json()),
          fetch('/api/admin/security/active-sessions').then(r => r.json()),
          fetch('/api/admin/users').then(r => r.json()),
          fetch('/api/admin/ai-config').then(r => r.json()),
          fetch('/api/admin/cosmos/prompt-profile').then(r => r.json()),
          fetch('/api/admin/listener-status').then(r => r.json())
        ])

        if (nvrRes.status === 'fulfilled') {
          Object.assign(nvrConfig, nvrRes.value)
          nvrStatus.isDemo = !!nvrConfig.demo_mode
          nvrStatus.connected = true
        }
        if (camRes.status === 'fulfilled') allCameras.value = camRes.value.cameras || []
        if (sessRes.status === 'fulfilled') activeSessions.value = sessRes.value.sessions || []
        if (userRes.status === 'fulfilled') systemUsers.value = userRes.value || []
        if (aiRes.status === 'fulfilled') Object.assign(aiConfig, aiRes.value)
        if (cosRes.status === 'fulfilled') Object.assign(cosmosPrompt, cosRes.value)
        if (lisRes.status === 'fulfilled') Object.assign(listenerStatus, lisRes.value)
      } catch (err) {
        console.error('Error loading dashboard data:', err)
      } finally {
        loading.value = false
      }
    }

    onMounted(loadData)

    return {
      loading,
      nvrConfig,
      nvrStatus,
      allCameras,
      activeCamerasCount,
      activeSessions,
      systemUsers,
      aiConfig,
      cosmosPrompt,
      listenerStatus,
      loadData
    }
  }
})
</script>

